function mix(a){a=Math.imul(a^(a>>>16),2246822507);a=Math.imul(a^(a>>>13),3266489909);return (a^(a>>>16))>>>0}
function generate(seed,race,kingdom,slot=0){const p=roots[race]||roots[0],r=regions[kingdom]||regions[0];let x=mix((seed+Math.imul(slot+1,2654435761))>>>0);const pick=(arr)=>{x=mix(x+1597334677);return arr[x%arr.length]};const given=pick(p[0])+pick(r[0])+pick(p[1]);const family=pick(r[1])+pick(r[2])+'-'+pick(p[0])+pick(p[1]);return {given,family,full:given+' '+family,culture:race+'-'+kingdom}}
